-- 007_dre_despesa_detalhada.sql
-- Lançamentos individuais de despesa — Jan–Abr 2026 (3.239 linhas)
-- Execute no Supabase Dashboard > SQL Editor
-- ============================================================

CREATE TABLE IF NOT EXISTS public.dre_despesa_detalhada (
  id               serial PRIMARY KEY,
  mes_ano          varchar(7)   NOT NULL,
  data_competencia date,
  descricao        text,
  categoria        varchar(100),
  valor            numeric      NOT NULL,
  classificacao_dre varchar(100),
  tipo_despesa     varchar(60),
  criado_em        timestamptz  DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_dre_despesa_mes ON public.dre_despesa_detalhada(mes_ano);
CREATE INDEX IF NOT EXISTS idx_dre_despesa_tipo ON public.dre_despesa_detalhada(tipo_despesa);
CREATE INDEX IF NOT EXISTS idx_dre_despesa_cls ON public.dre_despesa_detalhada(classificacao_dre);

ALTER TABLE public.dre_despesa_detalhada ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "dre_despesa_read" ON public.dre_despesa_detalhada;
CREATE POLICY "dre_despesa_read" ON public.dre_despesa_detalhada FOR SELECT TO authenticated, anon USING (true);
DROP POLICY IF EXISTS "dre_despesa_manage" ON public.dre_despesa_detalhada;
CREATE POLICY "dre_despesa_manage" ON public.dre_despesa_detalhada FOR ALL TO service_role USING (true) WITH CHECK (true);







